#define MAX_RANDOM_SOURCES 50
#define NSL_INVALID_ID 0

typedef unsigned int nslSoundId;
typedef unsigned int nslSourceId;
typedef unsigned int nslEmitterId;

class Random
{
public:
  unsigned int NextRand();
};

extern Random *g_random_ptr;

inline float random()
{
  float r = g_random_ptr->NextRand() * (1.0f/32767);
  return r;
}

inline int random(int end)
{
  unsigned int r = g_random_ptr->NextRand();
  return r % end;
}

extern nslSoundId nslAddSound(nslSourceId source);
extern void nslPlaySound(nslSoundId sound);

class RandomVO
{
private:
  float             probability;
  nslSoundId        thisSound;
  int               totalSources;
  int               numUsedSources;
  int               numUnusedSources;
  bool              valid;
  int               lastSource;
  int               probablity;
  nslEmitterId      pos;
  nslSourceId sources[MAX_RANDOM_SOURCES];
  nslSourceId sourcesUsed[MAX_RANDOM_SOURCES];
  nslSourceId sourcesUnused[MAX_RANDOM_SOURCES];
public:
  int  play();
};

int RandomVO::play()
{
  int index = 0;
  if (!valid) return NSL_INVALID_ID;
  if (totalSources == 0) return NSL_INVALID_ID;

  // Have we run out?
  // Then move them all back
  if (numUnusedSources == 0) {
    for (int i=0; i < totalSources; i++)
    {
      sourcesUnused[i] = sources[i];
      sourcesUsed[i] = NSL_INVALID_ID;
    }
    numUnusedSources = totalSources;
    numUsedSources = 0;
  }
  // Check random factor to see if we should
  // play
  float val = random();
  if (val > probability)
    return NSL_INVALID_ID;

  // Random number between 0 and unused - 1
  int src = random(numUnusedSources);

  for (int i=0; i < totalSources; i++)
  {
    if (sources[i] == sourcesUnused[src])
      index = i;
  }
  lastSource = sourcesUnused[src];
  if (lastSource != NSL_INVALID_ID)
  {
    //  Create that sound
    thisSound = nslAddSound(lastSource);
    if (thisSound != NSL_INVALID_ID)
    {
      // add it to the used list
      sourcesUsed[numUsedSources++] = src;
      // Move the last one to the spot that we removed
      sourcesUnused[src] = sourcesUnused[--numUnusedSources];
      // Play it.. it will get done soon enough
      if (thisSound != NSL_INVALID_ID)
        nslPlaySound(thisSound);
    }
    else
    {
      return NSL_INVALID_ID;
    }
  }
  else
  {
    return NSL_INVALID_ID;
  }
  return thisSound;
}
